mkitem!{mktrait!{# [doc = " A trait implemented for all `X<'a>` types that can be safely and"] # [doc = " efficiently converted to `X<'tcx>` as long as they are part of the"] # [doc = " provided `TyCtxt<'tcx>`."] # [doc = " This can be done, for example, for `Ty<'tcx>` or `GenericArgsRef<'tcx>`"] # [doc = " by looking them up in their respective interners."] # [doc = ""] # [doc = " However, this is still not the best implementation as it does"] # [doc = " need to compare the components, even for interned values."] # [doc = " It would be more efficient if `TypedArena` provided a way to"] # [doc = " determine whether the address is in the allocated range."] # [doc = ""] # [doc = " `None` is returned if the value or one of the components is not part"] # [doc = " of the provided context."] # [doc = " For `Ty`, `None` can be returned if either the type interner doesn't"] # [doc = " contain the `TyKind` key or if the address of the interned"] # [doc = " pointer differs. The latter case is possible if a primitive type,"] # [doc = " e.g., `()` or `u8`, was interned in a different context."] pub trait Lift < I > : std :: fmt :: Debug { type Lifted : std :: fmt :: Debug ; fn lift_to_interner (self , cx : I) -> Option < Self :: Lifted > ; }}}